import { Sparkles } from 'lucide-react'
import type { Task } from '../api'

interface SkillChipsProps {
  task: Task
  retrying: boolean
  onRetry: () => void
}

// skills generated by gemini show a sparkle beside them
// if gemini failed, show "not identified" with a retry link instead
export default function SkillChips({ task, retrying, onRetry }: SkillChipsProps) {
  if (task.skillsPending) {
    return (
      <span className="inline-flex items-center gap-2 text-xs">
        <span className="rounded-full border border-amber-200 bg-amber-50 px-2.5 py-0.5 text-amber-800">
          Skills not identified
        </span>
        <button
          type="button"
          disabled={retrying}
          onClick={onRetry}
          className="font-medium text-violet-600 underline disabled:opacity-50"
        >
          {retrying ? 'Retrying...' : 'Retry'}
        </button>
      </span>
    )
  }

  const byAi = task.skillsSource === 'ai'
  return (
    <span className="inline-flex flex-wrap items-center gap-1.5">
      {task.skills.map((skill) => (
        <span
          key={skill.id}
          className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs font-medium ${
            byAi
              ? 'border-fuchsia-200 bg-linear-to-r from-violet-50 to-fuchsia-50 text-violet-800'
              : 'border-indigo-100 bg-indigo-50 text-indigo-800'
          }`}
        >
          {byAi && <Sparkles size={11} className="text-fuchsia-400" aria-hidden="true" />}
          {skill.name}
        </span>
      ))}
      {byAi && <span className="sr-only">(skills identified by AI)</span>}
    </span>
  )
}
